"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { ResourceError, ViewerFormatError } from "@/lib/viewer-errors"
import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource"
import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source"
import {
  buildXlsxSourceFromCompact,
  resolveXlsxSheetChange,
  XlsxSourceCache,
  type CompactSheet,
  type XlsxSheetMeta,
  type XlsxSource,
} from "@/lib/xlsx-workbook"
import {
  type XlsxWorkerRequest,
  type XlsxWorkerResponse,
} from "@/lib/xlsx-worker-protocol"
import { ViewerErrorBoundary } from "@/components/ui/viewer-error"
import { XlsxGrid, XlsxGridSkeleton } from "@/components/ui/xlsx-grid"
import { XlsxSheetTabs } from "@/components/ui/xlsx-sheet-tabs"
import { XlsxToolbar, XlsxToolbarSkeleton } from "@/components/ui/xlsx-toolbar"
import {
  resolveLoadedScrollTarget,
  toInternalCellRef,
  type InternalXlsxCellRef,
  type PendingXlsxScrollTarget,
  type PublicXlsxCellRef,
  type XlsxScrollRequest,
} from "@/components/ui/xlsx-viewer-scroll"

const sourceCache = new XlsxSourceCache({ maxEntries: 4 })

async function buildXlsxSource(resource: ViewerResource): Promise<XlsxSource> {
  try {
    const buffer = await resource.readArrayBuffer()
    return buildXlsxSourceFromCompact(await parseWorkbookInWorker(buffer))
  } catch (error) {
    if (error instanceof ResourceError) throw error
    throw new ViewerFormatError({
      format: "xlsx",
      kind: "parse_failed",
      message: "Failed to parse spreadsheet.",
      cause: error,
    })
  }
}

function parseWorkbookInWorker(buffer: ArrayBuffer): Promise<CompactSheet[]> {
  return new Promise((resolve, reject) => {
    if (typeof Worker === "undefined") {
      reject(new Error("Web Workers are unavailable in this environment"))
      return
    }

    const worker = new Worker(
      new URL("./xlsx-viewer.worker", import.meta.url),
      { type: "module" }
    )
    worker.onmessage = (event: MessageEvent<XlsxWorkerResponse>) => {
      worker.terminate()
      if (event.data.type === "workbook") {
        resolve(event.data.sheets)
      } else {
        reject(new Error(event.data.message))
      }
    }
    worker.onerror = (event) => {
      worker.terminate()
      reject(new Error(event.message || "Spreadsheet worker failed"))
    }
    const request: XlsxWorkerRequest = { type: "parse_workbook", buffer }
    worker.postMessage(request, [buffer])
  })
}

function getXlsxSource(resource: ViewerResource): Promise<XlsxSource> {
  return sourceCache.get(resource.cacheKey, () => buildXlsxSource(resource))
}

/** Client gate without an effect: false during SSR, true after hydration. */
function useIsClient() {
  return React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false
  )
}

export type XlsxDocumentSource = UrlViewerSource | BlobViewerSource

export interface XlsxViewerProps {
  /** Canonical spreadsheet source. */
  source: XlsxDocumentSource
  className?: string
  toolbar?: boolean
  /** Sheet shown first. Defaults to 0. */
  defaultSheetIndex?: number
  /** Fired with the active sheet index on tab switch and imperative sheet changes. */
  onSheetChange?: (index: number) => void
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean
  /** Rendered as a full-width strip directly below the toolbar. */
  header?: React.ReactNode
  /** Rendered as a left rail alongside the grid. */
  aside?: React.ReactNode
  /** Public compatibility coordinates: 0-based row + column on `sheet`. */
  activeCell?: XlsxCellRef | null
  /**
   * Render the scrolling grid inside a shadow root, isolating it from host page
   * style invalidation while preserving inherited theme variables.
   */
  isolateStyles?: boolean
}

export type XlsxCellRef = PublicXlsxCellRef

export interface XlsxViewerHandle {
  scrollToCell: (
    sheet: number,
    row: number,
    col: number,
    options?: { behavior?: ScrollBehavior }
  ) => void
  getViewportElement: () => HTMLDivElement | null
}

export const XlsxViewer = React.forwardRef<XlsxViewerHandle, XlsxViewerProps>(
  function XlsxViewer(props, ref) {
    const isClient = useIsClient()
    const resource = React.useMemo(
      () => createViewerResource(props.source),
      [props.source]
    )
    if (!isClient) {
      return (
        <XlsxViewerFallback className={props.className} bare={props.bare} />
      )
    }
    return (
      <ViewerErrorBoundary
        className={props.className}
        download={resource.getOriginalDownload()}
        format="xlsx"
        resetKey={resource.cacheKey}
        sourceKind={resource.source.kind}
      >
        <React.Suspense
          fallback={
            <XlsxViewerFallback className={props.className} bare={props.bare} />
          }
        >
          <XlsxViewerSession
            key={resource.cacheKey}
            {...props}
            forwardedRef={ref}
            resource={resource}
          />
        </React.Suspense>
      </ViewerErrorBoundary>
    )
  }
)

function XlsxViewerSession({
  resource,
  className,
  toolbar = true,
  defaultSheetIndex = 0,
  onSheetChange,
  bare = false,
  header,
  aside,
  activeCell,
  isolateStyles = false,
  forwardedRef,
}: XlsxViewerProps & {
  resource: ViewerResource
  forwardedRef?: React.ForwardedRef<XlsxViewerHandle>
}) {
  const [activeSheetIndex, setActiveSheetIndex] = React.useState(
    Math.max(0, defaultSheetIndex)
  )
  const [scale, setScale] = React.useState(1)
  const [scrollRequest, setScrollRequest] =
    React.useState<XlsxScrollRequest | null>(null)
  const [pendingScrollTarget, setPendingScrollTarget] =
    React.useState<PendingXlsxScrollTarget | null>(null)
  const scrollNonce = React.useRef(0)
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null)
  const [sheets, setSheets] = React.useState<XlsxSheetMeta[] | null>(null)

  const reportSource = React.useCallback((source: XlsxSource) => {
    setSheets(source.sheets)
    setActiveSheetIndex((sheetIndex) =>
      clamp(sheetIndex, 0, Math.max(0, source.sheets.length - 1))
    )
  }, [])

  const setLoadedSheetIndex = React.useCallback(
    (sheetIndex: number) => {
      const change = resolveXlsxSheetChange({
        activeSheet: activeSheetIndex,
        requestedSheet: sheetIndex,
        sheetCount: sheets?.length,
      })
      if (!change.accepted) return false
      if (change.changed) {
        setActiveSheetIndex(change.sheetIndex)
        onSheetChange?.(change.sheetIndex)
      }
      return true
    },
    [activeSheetIndex, onSheetChange, sheets]
  )

  const issueLoadedScrollTarget = React.useCallback(
    (target: PendingXlsxScrollTarget) => {
      if (!sheets) return false

      const resolved = resolveLoadedScrollTarget({
        activeSheetIndex,
        target,
        sheets,
      })
      if (!resolved) return false

      if (resolved.changed) {
        setActiveSheetIndex(resolved.sheetIndex)
        onSheetChange?.(resolved.sheetIndex)
      }

      scrollNonce.current += 1
      setScrollRequest({
        ...resolved.request,
        nonce: scrollNonce.current,
      })
      return true
    },
    [activeSheetIndex, onSheetChange, sheets]
  )

  React.useEffect(() => {
    if (!pendingScrollTarget || !sheets) return
    setPendingScrollTarget(null)
    issueLoadedScrollTarget(pendingScrollTarget)
  }, [issueLoadedScrollTarget, pendingScrollTarget, sheets])

  React.useImperativeHandle(
    forwardedRef,
    () => ({
      scrollToCell: (sheet, row, col, options) => {
        const target = toInternalCellRef({ sheet, row, col })
        if (!target) return

        const pendingTarget = {
          ...target,
          behavior: options?.behavior ?? "smooth",
        }
        if (!sheets) {
          setPendingScrollTarget(pendingTarget)
          return
        }

        issueLoadedScrollTarget(pendingTarget)
      },
      getViewportElement: () => viewportElementRef.current,
    }),
    [issueLoadedScrollTarget, sheets]
  )

  const isReady = sheets != null
  const activeSheet = sheets?.[activeSheetIndex]
  const activeCellTarget = toInternalCellRef(activeCell)
  const zoom = (factor: number) =>
    setScale((value) => clamp(value * factor, 0.25, 5))

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="xlsx-viewer"
    >
      {toolbar ? (
        <XlsxToolbar
          downloadAction={resource.getOriginalDownload()}
          sheet={activeSheet}
          isReady={isReady}
          scale={scale}
          onZoomOut={() => zoom(1 / 1.2)}
          onZoomIn={() => zoom(1.2)}
          onResetZoom={() => setScale(1)}
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        {aside ? (
          <div data-slot="xlsx-viewer-aside" className="flex-shrink-0">
            {aside}
          </div>
        ) : null}
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {header ? <div data-slot="xlsx-viewer-header">{header}</div> : null}
          <React.Suspense fallback={<XlsxGridSkeleton />}>
            <XlsxSheet
              resource={resource}
              activeSheetIndex={activeSheetIndex}
              scale={scale}
              onReportSource={reportSource}
              activeCell={activeCellTarget}
              scrollRequest={scrollRequest}
              isolateStyles={isolateStyles}
              viewportRef={viewportElementRef}
            />
          </React.Suspense>
        </div>
      </div>

      {sheets ? (
        <XlsxSheetTabs
          sheets={sheets}
          activeSheetIndex={activeSheetIndex}
          onSelectSheet={setLoadedSheetIndex}
        />
      ) : null}
    </div>
  )
}

function XlsxSheet({
  resource,
  activeSheetIndex,
  scale,
  onReportSource,
  activeCell,
  scrollRequest,
  isolateStyles,
  viewportRef,
}: {
  resource: ViewerResource
  activeSheetIndex: number
  scale: number
  onReportSource: (source: XlsxSource) => void
  activeCell?: InternalXlsxCellRef | null
  scrollRequest?: XlsxScrollRequest | null
  isolateStyles: boolean
  viewportRef?: React.RefObject<HTMLDivElement | null>
}) {
  const source = React.use(getXlsxSource(resource))

  React.useEffect(() => {
    onReportSource(source)
  }, [source, onReportSource])

  const sheetIndex = clamp(
    activeSheetIndex,
    0,
    Math.max(0, source.sheets.length - 1)
  )
  const sheet = source.sheets[sheetIndex]
  const getCell = React.useCallback(
    (rowIndex: number, columnIndex: number) =>
      source.getCell(sheetIndex, rowIndex, columnIndex),
    [source, sheetIndex]
  )
  const activeCellInSheet =
    activeCell && activeCell.sheetIndex === sheetIndex
      ? { rowIndex: activeCell.rowIndex, columnIndex: activeCell.columnIndex }
      : null
  const scrollRequestInSheet =
    scrollRequest && scrollRequest.sheetIndex === sheetIndex
      ? scrollRequest
      : null

  return (
    <XlsxGrid
      key={sheetIndex}
      rowCount={sheet?.rowCount ?? 0}
      columnCount={sheet?.columnCount ?? 0}
      sheetName={sheet?.name ?? `Sheet ${sheetIndex + 1}`}
      getCell={getCell}
      scale={scale}
      activeCell={activeCellInSheet}
      scrollRequest={scrollRequestInSheet}
      isolateStyles={isolateStyles}
      viewportRef={viewportRef}
    />
  )
}

function XlsxViewerFallback({
  className,
  bare = false,
}: {
  className?: string
  bare?: boolean
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "h-full bg-muted/20" : "rounded-xl border bg-muted/30",
        className
      )}
      data-slot="xlsx-viewer"
    >
      <XlsxToolbarSkeleton />
      <div className="flex min-h-0 flex-1">
        <XlsxGridSkeleton />
      </div>
    </div>
  )
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

"use client"

import * as React from "react"

import { xlsxColumnLabel, type XlsxCell } from "@/lib/xlsx-workbook"
import {
  fixedGridColumnWidths,
} from "@/components/ui/fixed-grid-columns"
import {
  getFixedGridCanvasStyle,
  getFixedGridRowWindowStyle,
} from "@/components/ui/fixed-grid-layout"
import { buildVirtualGridTemplate } from "@/components/ui/fixed-grid-template"
import { useFixedGridVirtualization } from "@/components/ui/fixed-grid-virtualization"
import type { GridCellCoordinate } from "@/components/ui/fixed-grid-selection"
import { FixedGridViewport } from "@/components/ui/fixed-grid-viewport"
import { HeaderAwareScrollbar } from "@/components/ui/header-aware-scrollbar"
import {
  XLSX_BASE_COLUMN_WIDTH,
  XLSX_BASE_FONT_SIZE,
  XLSX_BASE_GUTTER_WIDTH,
  XLSX_BASE_ROW_HEIGHT,
} from "@/components/ui/xlsx-grid-constants"
import {
  Spacer,
  XlsxGridRow,
  type XlsxGridColumnItem,
} from "@/components/ui/xlsx-grid-row"
import { XLSX_SCROLLBAR_CSS } from "@/components/ui/xlsx-grid-scrollbar"
import { ScrollerShell } from "@/components/ui/xlsx-shadow-scope"

export { XlsxGridSkeleton } from "@/components/ui/xlsx-grid-skeleton"

export interface XlsxScrollRequest {
  sheetIndex: number
  rowIndex: number
  columnIndex: number
  behavior: ScrollBehavior
  nonce: number
}

type XlsxGridCellRef = GridCellCoordinate

export function XlsxGrid({
  rowCount,
  columnCount,
  getCell,
  sheetName,
  scale,
  activeCell,
  scrollRequest,
  isolateStyles,
  viewportRef,
}: {
  rowCount: number
  columnCount: number
  sheetName: string
  getCell: (rowIndex: number, columnIndex: number) => XlsxCell
  scale: number
  activeCell?: XlsxGridCellRef | null
  scrollRequest?: XlsxScrollRequest | null
  isolateStyles: boolean
  viewportRef?: React.RefObject<HTMLDivElement | null>
}) {
  const rowHeight = Math.round(XLSX_BASE_ROW_HEIGHT * scale)
  const columnWidth = Math.round(XLSX_BASE_COLUMN_WIDTH * scale)
  const gutterWidth = Math.round(XLSX_BASE_GUTTER_WIDTH * scale)
  const fontSize = XLSX_BASE_FONT_SIZE * scale

  const scrollRef = React.useRef<HTMLDivElement>(null)
  const setScrollElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      scrollRef.current = element
      if (viewportRef) viewportRef.current = element
    },
    [viewportRef]
  )

  const {
    virtualRows,
    totalRowSize,
    totalColumnSize,
    columnItems: virtualColumnItems,
    leftPad,
    rightPad,
    scrollToCell,
  } = useFixedGridVirtualization({
    rowCount,
    columnCount,
    rowSize: rowHeight,
    columnSize: columnWidth,
    rowOverscan: 30,
    columnOverscan: 30,
    scrollRef,
  })

  const requestNonce = scrollRequest?.nonce
  React.useEffect(() => {
    if (!scrollRequest) return
    scrollToCell({
      rowIndex: scrollRequest.rowIndex,
      columnIndex: scrollRequest.columnIndex,
      behavior: scrollRequest.behavior,
      align: "center",
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [requestNonce])

  const columnItems = React.useMemo(
    () =>
      virtualColumnItems.map((item) => ({
        key: String(item.index),
        widthPx: item.widthPx,
        metadata: { columnIndex: item.index },
      })) satisfies XlsxGridColumnItem[],
    [virtualColumnItems]
  )

  const gridTemplate = React.useMemo(
    () =>
        buildVirtualGridTemplate({
          leadingWidth: gutterWidth,
          leftPad,
          columnWidths: fixedGridColumnWidths(columnItems),
          rightPad,
        }),
    [gutterWidth, leftPad, columnItems, rightPad]
  )
  const totalWidth = gutterWidth + totalColumnSize

  if (rowCount === 0 || columnCount === 0) {
    return (
      <div
        className="flex flex-1 items-center justify-center bg-card text-xs text-muted-foreground"
        role="status"
        aria-label={`${sheetName} is empty`}
      >
        Empty sheet
      </div>
    )
  }

  return (
    <div
      className="flex min-h-0 flex-1 flex-col bg-card"
      style={{ fontSize }}
      data-slot="xlsx-grid"
    >
      <ScrollerShell
        isolate={isolateStyles}
        className="relative min-h-0 flex-1"
      >
        <style>{XLSX_SCROLLBAR_CSS}</style>
        <FixedGridViewport
          scrollRef={setScrollElement}
          dataSlot="xlsx-body"
          role="grid"
          aria-label={sheetName}
          aria-rowcount={rowCount}
          aria-colcount={columnCount}
          tabIndex={0}
        >
          <div
            style={getFixedGridCanvasStyle({
              width: totalWidth,
            })}
          >
            <div
              className="sticky top-0 z-20 grid border-b"
              style={{
                gridTemplateColumns: gridTemplate,
                height: rowHeight,
                backgroundColor:
                  "color-mix(in oklab, var(--card) 92%, var(--foreground))",
              }}
              aria-hidden
            >
              <div
                className="sticky left-0 z-10 border-r bg-[color-mix(in_oklab,var(--card)_94%,var(--foreground))]"
                style={{ height: rowHeight }}
              />
              <Spacer width={leftPad} />
              {columnItems.map((item) => (
                <div
                  key={item.key}
                  className="flex items-center justify-center border-r font-medium text-muted-foreground last:border-r-0"
                >
                  {xlsxColumnLabel(item.metadata.columnIndex)}
                </div>
              ))}
              <Spacer width={rightPad} />
            </div>

            <div
              style={getFixedGridRowWindowStyle({ height: totalRowSize })}
            >
              {virtualRows.map((virtualRow) => (
                <XlsxGridRow
                  key={virtualRow.index}
                  rowIndex={virtualRow.index}
                  getCell={getCell}
                  gridTemplate={gridTemplate}
                  rowHeight={rowHeight}
                  columnItems={columnItems}
                  leftPad={leftPad}
                  rightPad={rightPad}
                  start={virtualRow.start}
                  activeColumnIndex={
                    activeCell?.rowIndex === virtualRow.index
                      ? activeCell.columnIndex
                      : null
                  }
                />
              ))}
            </div>
          </div>
        </FixedGridViewport>
        <HeaderAwareScrollbar scrollRef={scrollRef} headerHeight={rowHeight} />
      </ScrollerShell>
    </div>
  )
}

"use client"

import * as React from "react"

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

const MINIMUM_ROW_WINDOW = 32
const INITIAL_COLUMN_WINDOW = 8

export interface FixedGridColumnItem {
  index: number
  widthPx: number
}

export interface FixedGridVirtualItem {
  index: number
  start: number
  size: number
  end: number
}

export interface FixedGridScrollTarget {
  rowIndex: number
  columnIndex: number
  align?: "start" | "center" | "end" | "auto"
  behavior?: ScrollBehavior
}

export interface FixedRowScrollTarget {
  rowIndex: number
  align?: "start" | "center" | "end" | "auto"
  behavior?: ScrollBehavior
}

export function useFixedGridVirtualization({
  rowCount,
  columnCount,
  rowSize,
  columnSize,
  rowOverscan,
  columnOverscan,
  jumpRowOverscan = rowOverscan,
  jumpColumnOverscan = columnOverscan,
  scrollRef,
  scrollElement,
  virtualizeColumns = true,
}: {
  rowCount: number
  columnCount: number
  rowSize: number
  columnSize: number
  rowOverscan: number
  columnOverscan: number
  jumpRowOverscan?: number
  jumpColumnOverscan?: number
  scrollRef: React.RefObject<HTMLElement | null>
  scrollElement?: HTMLElement | null
  virtualizeColumns?: boolean
}) {
  const resolvedScrollElement = useResolvedScrollElement({
    scrollRef,
    scrollElement,
  })
  const viewport = useFixedGridViewport(resolvedScrollElement)

  const totalRowSize = rowCount * rowSize
  const totalColumnSize = columnCount * columnSize
  const activeRowOverscan = viewport.isJumpingRows
    ? jumpRowOverscan
    : rowOverscan
  const activeColumnOverscan =
    viewport.isJumpingColumns || viewport.isJumpingRows
      ? jumpColumnOverscan
      : columnOverscan

  const virtualRows = React.useMemo(
    () =>
      fixedVirtualItems({
        count: rowCount,
        size: rowSize,
        scrollOffset: viewport.scrollTop,
        viewportSize: viewport.clientHeight,
        overscan: activeRowOverscan,
        minimumVisibleCount: MINIMUM_ROW_WINDOW,
      }),
    [
      rowCount,
      rowSize,
      viewport.scrollTop,
      viewport.clientHeight,
      activeRowOverscan,
    ]
  )

  const columnWindow = React.useMemo<{
    columnItems: FixedGridColumnItem[]
    leftPad: number
    rightPad: number
  }>(() => {
    if (!virtualizeColumns) {
      return {
        columnItems: Array.from({ length: columnCount }, (_, index) => ({
          index,
          widthPx: columnSize,
        })),
        leftPad: 0,
        rightPad: 0,
      }
    }

    const virtualColumns = fixedVirtualItems({
      count: columnCount,
      size: columnSize,
      scrollOffset: viewport.scrollLeft,
      viewportSize: viewport.clientWidth,
      overscan: activeColumnOverscan,
      minimumVisibleCount: INITIAL_COLUMN_WINDOW,
    })

    return {
      columnItems: virtualColumns.map((item) => ({
        index: item.index,
        widthPx: item.size,
      })),
      leftPad: virtualColumns.length ? virtualColumns[0].start : 0,
      rightPad: virtualColumns.length
        ? totalColumnSize - virtualColumns[virtualColumns.length - 1].end
        : 0,
    }
  }, [
    virtualizeColumns,
    columnCount,
    columnSize,
    viewport.scrollLeft,
    viewport.clientWidth,
    activeColumnOverscan,
    totalColumnSize,
  ])

  const scrollToCell = React.useCallback(
    ({
      rowIndex,
      columnIndex,
      align = "center",
      behavior = "smooth",
    }: FixedGridScrollTarget) => {
      const scrollElement = scrollRef.current
      if (!scrollElement) return
      scrollElement.scrollTo({
        top: fixedScrollOffset({
          index: rowIndex,
          itemSize: rowSize,
          viewportSize: scrollElement.clientHeight,
          align,
        }),
        left: fixedScrollOffset({
          index: columnIndex,
          itemSize: columnSize,
          viewportSize: scrollElement.clientWidth,
          align,
        }),
        behavior,
      })
    },
    [columnSize, rowSize, scrollRef]
  )

  return {
    virtualRows,
    totalRowSize,
    totalColumnSize,
    scrollToCell,
    ...columnWindow,
  }
}

export function useFixedRowVirtualization({
  rowCount,
  rowSize,
  rowOverscan,
  jumpRowOverscan = rowOverscan,
  scrollRef,
}: {
  rowCount: number
  rowSize: number
  rowOverscan: number
  jumpRowOverscan?: number
  scrollRef: React.RefObject<HTMLElement | null>
}) {
  const [range, setRange] = React.useState({ start: 0, end: 0 })
  const rangeRef = React.useRef(range)
  const rafRef = React.useRef(0)
  const totalRowSize = rowCount * rowSize

  const setMeasuredRange = React.useCallback((next: typeof range) => {
    const current = rangeRef.current
    if (current.start === next.start && current.end === next.end) return
    rangeRef.current = next
    setRange(next)
  }, [])

  const measure = React.useCallback(() => {
    const scrollElement = scrollRef.current
    if (!scrollElement || rowCount <= 0 || rowSize <= 0) {
      setMeasuredRange({ start: 0, end: 0 })
      return
    }

    const scrollTop = scrollElement.scrollTop
    const viewportHeight = scrollElement.clientHeight
    const firstVisibleRow = Math.floor(scrollTop / rowSize)
    const visibleRowCount = Math.ceil(viewportHeight / rowSize)
    const previous = rangeRef.current
    const isJumping =
      Math.abs(firstVisibleRow - previous.start) > visibleRowCount * 0.45
    const activeOverscan = isJumping ? jumpRowOverscan : rowOverscan
    const start = Math.max(0, firstVisibleRow - activeOverscan)
    const end = Math.min(
      rowCount,
      firstVisibleRow + visibleRowCount + activeOverscan
    )

    if (previous.end > rowCount || previous.start >= rowCount) {
      setMeasuredRange({ start, end })
      return
    }

    const bufferRows = Math.max(1, Math.floor(activeOverscan / 2))
    const visibleStart = firstVisibleRow
    const visibleEnd = Math.min(rowCount, firstVisibleRow + visibleRowCount)
    const hasBeforeBuffer =
      previous.start === 0 || visibleStart >= previous.start + bufferRows
    const hasAfterBuffer =
      previous.end === rowCount || visibleEnd <= previous.end - bufferRows

    if (hasBeforeBuffer && hasAfterBuffer) return
    setMeasuredRange({ start, end })
  }, [
    jumpRowOverscan,
    rowCount,
    rowOverscan,
    rowSize,
    scrollRef,
    setMeasuredRange,
  ])

  React.useLayoutEffect(() => {
    measure()
  }, [measure])

  React.useEffect(() => {
    const scrollElement = scrollRef.current
    if (!scrollElement) return

    const scheduleMeasure = () => {
      if (rafRef.current) return
      rafRef.current = requestAnimationFrame(() => {
        rafRef.current = 0
        measure()
      })
    }

    scrollElement.addEventListener("scroll", scheduleMeasure, {
      passive: true,
    })
    const observer = new ResizeObserver(scheduleMeasure)
    observer.observe(scrollElement)
    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current)
      scrollElement.removeEventListener("scroll", scheduleMeasure)
      observer.disconnect()
    }
  }, [scrollRef, measure])

  const virtualRows = React.useMemo(
    () =>
      Array.from({ length: range.end - range.start }, (_, offset) => {
        const index = range.start + offset
        const start = index * rowSize
        return {
          index,
          start,
          size: rowSize,
          end: start + rowSize,
        }
      }),
    [range, rowSize]
  )

  const scrollToRow = React.useCallback(
    ({
      rowIndex,
      align = "center",
      behavior = "smooth",
    }: FixedRowScrollTarget) => {
      const scrollElement = scrollRef.current
      if (!scrollElement) return
      scrollElement.scrollTo({
        top: fixedScrollOffset({
          index: rowIndex,
          itemSize: rowSize,
          viewportSize: scrollElement.clientHeight,
          align,
        }),
        behavior,
      })
    },
    [rowSize, scrollRef]
  )

  return {
    virtualRows,
    totalRowSize,
    scrollToRow,
  }
}

interface FixedGridViewport {
  scrollTop: number
  scrollLeft: number
  clientHeight: number
  clientWidth: number
  isJumpingRows: boolean
  isJumpingColumns: boolean
}

interface FixedVirtualWindow {
  count: number
  size: number
  scrollOffset: number
  viewportSize: number
  overscan: number
  minimumVisibleCount?: number
}

function useResolvedScrollElement({
  scrollRef,
  scrollElement,
}: {
  scrollRef: React.RefObject<HTMLElement | null>
  scrollElement?: HTMLElement | null
}) {
  const [resolvedScrollElement, setResolvedScrollElement] =
    React.useState<HTMLElement | null>(scrollElement ?? null)

  useIsomorphicLayoutEffect(() => {
    const nextScrollElement = scrollElement ?? scrollRef.current
    setResolvedScrollElement((current) =>
      current === nextScrollElement ? current : nextScrollElement
    )
  }, [scrollElement, scrollRef])

  return resolvedScrollElement
}

function useFixedGridViewport(scrollElement: HTMLElement | null | undefined) {
  const [viewport, setViewport] = React.useState<FixedGridViewport>({
    scrollTop: 0,
    scrollLeft: 0,
    clientHeight: 0,
    clientWidth: 0,
    isJumpingRows: false,
    isJumpingColumns: false,
  })

  useIsomorphicLayoutEffect(() => {
    if (!scrollElement) return

    let frame = 0
    let lastScrollTop = scrollElement.scrollTop
    let lastScrollLeft = scrollElement.scrollLeft

    const readViewport = () => {
      frame = 0
      const scrollTop = scrollElement.scrollTop
      const scrollLeft = scrollElement.scrollLeft
      const clientHeight = scrollElement.clientHeight
      const clientWidth = scrollElement.clientWidth
      const rowDelta = Math.abs(scrollTop - lastScrollTop)
      const columnDelta = Math.abs(scrollLeft - lastScrollLeft)
      lastScrollTop = scrollTop
      lastScrollLeft = scrollLeft

      setViewport((current) => {
        const next: FixedGridViewport = {
          scrollTop,
          scrollLeft,
          clientHeight,
          clientWidth,
          isJumpingRows: rowDelta > clientHeight * 0.45,
          isJumpingColumns: columnDelta > clientWidth * 0.45,
        }
        return fixedGridViewportEqual(current, next) ? current : next
      })
    }

    const scheduleRead = () => {
      if (frame) return
      frame = requestAnimationFrame(readViewport)
    }

    readViewport()
    scrollElement.addEventListener("scroll", scheduleRead, { passive: true })
    const observer = new ResizeObserver(scheduleRead)
    observer.observe(scrollElement)

    return () => {
      if (frame) cancelAnimationFrame(frame)
      scrollElement.removeEventListener("scroll", scheduleRead)
      observer.disconnect()
    }
  }, [scrollElement])

  return viewport
}

export function fixedVirtualItems({
  count,
  size,
  scrollOffset,
  viewportSize,
  overscan,
  minimumVisibleCount = 1,
}: FixedVirtualWindow): FixedGridVirtualItem[] {
  if (!Number.isFinite(count) || !Number.isFinite(size)) return []
  const itemCount = Math.floor(count)
  if (itemCount <= 0 || size <= 0) return []
  const safeScrollOffset =
    Number.isFinite(scrollOffset) && scrollOffset > 0 ? scrollOffset : 0
  const safeViewportSize = Number.isFinite(viewportSize) ? viewportSize : 0
  const safeOverscan =
    Number.isFinite(overscan) && overscan > 0 ? Math.floor(overscan) : 0
  const safeMinimumVisibleCount =
    Number.isFinite(minimumVisibleCount) && minimumVisibleCount > 0
      ? Math.ceil(minimumVisibleCount)
      : 1
  const effectiveViewportSize = Math.max(
    safeViewportSize,
    size * safeMinimumVisibleCount
  )
  const visibleStart = clamp(
    Math.floor(safeScrollOffset / size),
    0,
    itemCount - 1
  )
  const visibleEnd = clamp(
    Math.ceil((safeScrollOffset + effectiveViewportSize) / size),
    visibleStart,
    itemCount - 1
  )
  const start = Math.max(0, visibleStart - safeOverscan)
  const end = Math.min(itemCount - 1, visibleEnd + safeOverscan)
  return Array.from({ length: end - start + 1 }, (_, offset) => {
    const index = start + offset
    const itemStart = index * size
    return {
      index,
      start: itemStart,
      size,
      end: itemStart + size,
    }
  })
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

export function fixedScrollOffset({
  index,
  itemSize,
  viewportSize,
  align,
}: {
  index: number
  itemSize: number
  viewportSize: number
  align: NonNullable<FixedGridScrollTarget["align"]>
}) {
  if (
    !Number.isFinite(index) ||
    !Number.isFinite(itemSize) ||
    !Number.isFinite(viewportSize) ||
    itemSize <= 0 ||
    viewportSize < 0
  ) {
    return 0
  }
  const start = index * itemSize
  if (align === "end") return Math.max(0, start - viewportSize + itemSize)
  if (align === "center") {
    return Math.max(0, start - viewportSize / 2 + itemSize / 2)
  }
  return Math.max(0, start)
}

function fixedGridViewportEqual(
  left: FixedGridViewport,
  right: FixedGridViewport
) {
  return (
    left.scrollTop === right.scrollTop &&
    left.scrollLeft === right.scrollLeft &&
    left.clientHeight === right.clientHeight &&
    left.clientWidth === right.clientWidth &&
    left.isJumpingRows === right.isJumpingRows &&
    left.isJumpingColumns === right.isJumpingColumns
  )
}

export function buildVirtualGridTemplate({
  leadingWidth,
  leftPad,
  columnWidths,
  rightPad,
}: {
  leadingWidth: number
  leftPad: number
  columnWidths: readonly number[]
  rightPad: number
}) {
  const columns = columnWidths.map(formatTemplateWidth).join(" ")
  return [
    formatTemplateWidth(leadingWidth),
    formatTemplateWidth(leftPad),
    columns,
    formatTemplateWidth(rightPad),
  ]
    .filter(Boolean)
    .join(" ")
}

function formatTemplateWidth(width: number) {
  return `${Number.isFinite(width) && width > 0 ? width : 0}px`
}

export interface FixedGridColumn<Metadata = unknown> {
  key: string
  widthPx: number
  metadata?: Metadata
}

export function buildFixedGridColumns<Item, Metadata = unknown>({
  items,
  getKey,
  getWidthPx,
  getMetadata,
}: {
  items: readonly Item[]
  getKey: (item: Item, index: number) => string
  getWidthPx: (item: Item, index: number) => number
  getMetadata?: (item: Item, index: number) => Metadata | undefined
}): FixedGridColumn<Metadata>[] {
  return items.map((item, index) => {
    const metadata = getMetadata?.(item, index)
    const widthPx = normalizeFixedGridColumnWidth(getWidthPx(item, index))
    return metadata === undefined
      ? {
          key: getKey(item, index),
          widthPx,
        }
      : {
          key: getKey(item, index),
          widthPx,
          metadata,
        }
  })
}

export function fixedGridColumnWidths(
  columns: readonly Pick<FixedGridColumn, "widthPx">[]
) {
  return columns.map((column) => normalizeFixedGridColumnWidth(column.widthPx))
}

function normalizeFixedGridColumnWidth(widthPx: number) {
  return Number.isFinite(widthPx) && widthPx > 0 ? widthPx : 0
}

import type * as React from "react"

type CssLength = number | string

export function getFixedGridCanvasStyle({
  width,
  minWidth = "100%",
  contain = false,
}: {
  width?: CssLength
  minWidth?: CssLength
  contain?: boolean
}): React.CSSProperties {
  return {
    position: "relative",
    ...cssLengthProperty("width", width),
    ...cssLengthProperty("minWidth", minWidth),
    ...(contain ? { contain: "layout paint style" } : null),
  }
}

export function getFixedGridRowWindowStyle({
  height,
  minWidth,
}: {
  height: CssLength
  minWidth?: CssLength
}): React.CSSProperties {
  return {
    position: "relative",
    ...cssLengthProperty("height", height),
    ...cssLengthProperty("minWidth", minWidth),
  }
}

function formatCssLength(value: CssLength | undefined) {
  if (typeof value !== "number") return value
  return Number.isFinite(value) && value >= 0 ? `${value}px` : undefined
}

function cssLengthProperty<Property extends "height" | "minWidth" | "width">(
  property: Property,
  value: CssLength | undefined
): Pick<React.CSSProperties, Property> | object {
  const formattedValue = formatCssLength(value)
  return formattedValue === undefined ? {} : { [property]: formattedValue }
}

export interface GridCellCoordinate {
  rowIndex: number
  columnIndex: number
}

export function isSameGridCell(
  left: GridCellCoordinate | null | undefined,
  right: GridCellCoordinate | null | undefined
) {
  return (
    isValidGridCellCoordinate(left) &&
    isValidGridCellCoordinate(right) &&
    left.rowIndex === right.rowIndex &&
    left.columnIndex === right.columnIndex
  )
}

export function gridCellKey({ rowIndex, columnIndex }: GridCellCoordinate) {
  if (!isValidGridCellCoordinate({ rowIndex, columnIndex })) return null
  return `${rowIndex}:${columnIndex}`
}

export function parseGridCellKey(key: string): GridCellCoordinate | null {
  const [rowIndexText, columnIndexText, extra] = key.split(":")
  if (extra !== undefined) return null
  if (!rowIndexText || !columnIndexText) return null
  if (!isUnsignedIntegerText(rowIndexText) || !isUnsignedIntegerText(columnIndexText)) {
    return null
  }

  const rowIndex = Number(rowIndexText)
  const columnIndex = Number(columnIndexText)
  if (!isValidGridCellCoordinate({ rowIndex, columnIndex })) {
    return null
  }

  return { rowIndex, columnIndex }
}

function isUnsignedIntegerText(value: string) {
  return /^(0|[1-9]\d*)$/.test(value)
}

function isValidGridCellCoordinate(
  coordinate: GridCellCoordinate | null | undefined
): coordinate is GridCellCoordinate {
  return (
    !!coordinate &&
    Number.isSafeInteger(coordinate.rowIndex) &&
    Number.isSafeInteger(coordinate.columnIndex) &&
    coordinate.rowIndex >= 0 &&
    coordinate.columnIndex >= 0
  )
}

